import{z as n,x as A,o as e,c as p,q as t,j as r,D as E,d as l,s,S as o}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"电子束邻近校正细节","description":"","frontmatter":{"title":"电子束邻近校正细节","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/mask-pec-detail.md","filePath":"litho/mask-pec-detail.md","lastUpdated":1791413859000}'),B={name:"litho/mask-pec-detail.md"};function d(D,a,C,h,m,_){const i=A("Mermaid");return e(),p("div",null,[a[2]||(a[2]=t('<h1 id="电子束邻近校正细节" tabindex="-1">电子束邻近校正细节 <a class="header-anchor" href="#电子束邻近校正细节" aria-label="Permalink to &quot;电子束邻近校正细节&quot;">​</a></h1><div class="epigraph"><p>双高斯核把前向与背向拆开；雾化是更平的第三层。细节错了，密度相关 CD 会在 PEC「已经打开」之后仍在走。</p><footer>—— 对照电子束 PEC 双高斯 / 雾化模型的通称；基础见写掩模邻近校正文献</footer></div><p><a href="/litho/mask-write-time">上一课</a>把写入小时钉成家族公式。缺口是剂量图本身：通称 PEC 课已经说了「调剂量不调多边形」，本课补核的阶次、校准与过校正。网格与炮数如何量化这张图，留给<a href="/litho/write-grid-shot-count">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/ebeam-mask-pec">电子束 PEC</a> 给出短程、长程、雾化三层图像。细节是：短程（前向散射 + 束斑）决定边锐与小助条能否存在；长程（背散射）核宽随加速电压与衬底 Z 变；雾化（腔体二次电子）更接近全版底板。三层若用一个有效高斯去拟合，疏密交界会出现无法用一层 MPC 修掉的斜坡。</p><p>缺口是<strong>核与校准集</strong>，不是再定义一次 PEC。把「PEC on」当成 CDU 已合格，会漏掉：核半径用错时，校正把误差搬到另一种节距。</p><h3 id="过校正振荡" tabindex="-1">过校正振荡 <a class="header-anchor" href="#过校正振荡" aria-label="Permalink to &quot;过校正振荡&quot;">​</a></h3><p>反解剂量是病态的：短程核把高频放大。正则不足时，密区剂量被砍过头，下一轮密度图又反过来，CD 随迭代摆。这与晶圆 OPC 振荡同构。工程上限制剂量动态范围、平滑密度图、分短/长程分别收敛。</p><p><span class="marginnote">EUV 吸收体与 DUV 铬的背散射不同。换膜系等于重测核，不能只改 MPC 表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>双高斯（或三高斯）拟合曝光测试：孤立/密集线、倒比、大面积垫。雾化用全版或大窗曝光单独标定。写入时卷积密度图得到本底，再按阈值模型求每炮或每像素剂量。多束路径在栅格上做同一件事，只是 primitive 从炮换成像素。</p>',11)),(e(),r(o,null,{default:E(()=>[s(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20LR%0A%20%20INV%5B%22%E5%8F%8D%E8%A7%A3%E5%89%82%E9%87%8F%20%E7%97%85%E6%80%81%E9%97%AE%E9%A2%98%22%5D%20--%3E%20CUT%5B%22%E5%AF%86%E5%8C%BA%E5%89%82%E9%87%8F%E8%A2%AB%E7%A0%8D%E8%BF%87%E5%A4%B4%22%5D%0A%20%20CUT%20--%3E%20DRIFT%5B%22%E7%96%8F%E5%AF%86%E4%BA%A4%E7%95%8C%20CD%20%E6%96%9C%E5%9D%A1%22%5D%0A%20%20DRIFT%20--%3E%20UPD%5B%22%E6%9B%B4%E6%96%B0%E5%AF%86%E5%BA%A6%E5%9B%BE%E4%B8%8E%E6%A0%A1%E5%87%86%22%5D%0A%20%20UPD%20--%3E%20SWING%5B%22%E4%B8%8B%E4%B8%80%E8%BD%AE%20CD%20%E5%8F%8D%E5%90%91%E6%91%86%22%5D%0A%20%20SWING%20--%3E%20REG%5B%22%E6%AD%A3%E5%88%99%E5%8C%96%20%E9%99%90%E5%8A%A8%E6%80%81%E8%8C%83%E5%9B%B4%20%E5%88%86%E6%A0%B8%E6%94%B6%E6%95%9B%22%5D%0A%20%20REG%20--%3E%20OK%5B%22%E5%89%82%E9%87%8F%E5%9B%BE%E7%A8%B3%E5%AE%9A%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><span class="marginnote">这张图回答的问题是：PEC「打开了」CD 为什么还会来回摆。反解剂量天生病态——短程核把高频放大，密区剂量一旦砍过头，下一轮密度图又反过来，正则化与限幅就是把这只摆锤按住的办法。</span></p><p><span class="marginnote">常见误区：初学者容易把「PEC on」当成 CDU 已合格。核半径用错时，校正只是把误差从一种节距搬到另一种节距；三层核（短程、背散射、雾化）拆得对不对，要靠校准集说话。</span></p><p>与写入时间的耦合：PEC 动态范围大 → 平均剂量或遍数涨 → 日历涨。为了赶货而缩小 PEC 范围，等于把残差推给 mask CDU。</p><p><span class="marginnote">数字实例：假设 PEC 把最密区的剂量压到基准的 \\(0.6\\) 倍、孤立区抬到 \\(1.5\\) 倍，平均剂量上去了，写入可能从 2 遍涨到 3 遍——写入时间直接涨五成。反过来看：若 PEC 限得太窄，被砍掉的那段动态范围就变成残差，进 mask CDU 的账。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>入射电子在胶中损失能量（前向），一部分从铬/石英或 EUV 多层回来（背向）。背向电子在微米量级叠加本底，本底与周围开口率成正比。显影阈值切在「本地 + 本底」上，故同样数据宽度在密区更胖。PEC 求的是让有效能量对齐的入射剂量。加速电压升高，背向核往往变宽，长程项更重——这是写模参数，不是晶圆 NA。</p><p><span class="marginnote">术语翻译：背散射就是电子打进基板后被弹回，在离入射点微米远处再交出能量，给周围「垫」一层本底；雾化则是更大尺度（腔体、整版）的共享底板。PEC 做的事就是预先少打或多打剂量，把这层垫底扣平，让每条边落在同一阈值上。</span></p><p><span class="marginnote">直觉类比：本底像整间屋子的底噪。隔壁开口越多（密区），你这间屋的底噪越高；显影阈值按总能量切，底噪高的地方，同样宽的开口就被垫得更宽——这就是「密区线更胖」的来历。</span></p><p>版边缺邻居，长程卷积要 pad 或改边界条件，否则边框 CD 像「写出来的 flare」。这与 <a href="/litho/six-inch-reticle">6 寸有效区</a> 直接相关。</p>',9)),(e(),r(o,null,{default:E(()=>[s(i,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEN%5B%22%E5%BC%80%E5%8F%A3%E5%AF%86%E5%BA%A6%E5%9B%BE%22%5D%20--%3E%20FWD%5B%22%E7%9F%AD%E7%A8%8B%E6%A0%B8%22%5D%0A%20%20DEN%20--%3E%20BACK%5B%22%E8%83%8C%E6%95%A3%E5%B0%84%E6%A0%B8%22%5D%0A%20%20DEN%20--%3E%20FOG%5B%22%E9%9B%BE%E5%8C%96%E5%BA%95%E6%9D%BF%22%5D%0A%20%20FWD%20--%3E%20DOSE%5B%22%E5%8F%8D%E8%A7%A3%E5%89%82%E9%87%8F%22%5D%0A%20%20BACK%20--%3E%20DOSE%0A%20%20FOG%20--%3E%20DOSE%0A%20%20DOSE%20--%3E%20CD%5B%22%E6%8E%A9%E6%A8%A1%20CD-%E5%AF%86%E5%BA%A6%E6%9B%B2%E7%BA%BF%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不发明核的微米半径表，不写某厂软件名。不把化学放大胶的酸扩散与电子核写成同一个 σ。PEC 细节不替代掩模检验。</p><p>后课默认：剂量图按多层核来；下一课问这张图落在多细的地址栅上、VSB 要多少炮才能实现它。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PEC 细节是短程 / 背向 / 雾化分核，不是一开开关。</li><li>过校正会振荡；动态范围与写入时间耦合。</li><li>版边要单独处理长程核；换吸收体要重测。</li><li>出处：电子束 PEC 双高斯与雾化校正通称；写掩模邻近文献。</li></ul>',5))])}const f=n(B,[["render",d]]);export{P as __pageData,f as default};
